                                OrderEffect.REVOKE_REPLACED_ORDER,
                                OrderEffect.RECORD_CDS_OVERRIDES,
                                OrderEffect.RECORD_CDS_GAPS,
                                OrderEffect.CREATE_CO_SIGN_TASK,
                                OrderEffect.EMIT_CHARGE_EVENT,
                                OrderEffect.TRACK_OPEN_ORDER,
                                OrderEffect.PUBLISH_ORDER_SIGNED,
                            ),
                        proposed = false,
                    ),
                    Transition(
                        index = 2,
                        from = setOf(OrderState.DRAFT),
                        on = OrderCommand.Discard,
                        guard = listOf(OrderPredicate.ACTOR_PRIVILEGED),
                        to = OrderState.REVOKED,
                        effects = listOf(),
                        proposed = false,
                    ),
                    Transition(
                        index = 3,
                        from = setOf(OrderState.DRAFT),
                        on = OrderCommand.DraftReviewDue,
                        guard = listOf(OrderPredicate.DRAFT_REVIEW_DUE),
                        to = OrderState.DRAFT,
                        effects = listOf(OrderEffect.CREATE_DRAFT_OWNER_TASK),
                        proposed = true,
                    ),
                    Transition(
                        index = 4,
                        from = setOf(OrderState.PENDING_VERIFICATION),
                        on = OrderCommand.Verify,
                        guard =
                            listOf(
                                OrderPredicate.NOT_RETURNED,
                                OrderPredicate.VERIFIER_IS_PHARMACIST,
                                OrderPredicate.VERIFIER_INDEPENDENT_OF_ORDERER,
                                OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED,
                                OrderPredicate.NOT_OFFLINE_WITHOUT_FULL_CDS,
                                OrderPredicate.LOCAL_HARD_STOPS_SATISFIED,
                                OrderPredicate.KB_HARD_STOP_NOT_FIRED,
                                OrderPredicate.INTERRUPTIVE_ALERTS_ANSWERED,
                                OrderPredicate.CDS_GAPS_REVIEWED,
                                OrderPredicate.CONTROL_SET_A_SATISFIED,
                            ),
                        to = OrderState.ACTIVE,
                        effects = listOf(OrderEffect.RECORD_VERIFICATION, OrderEffect.PUBLISH_MEDICATION_VERIFIED),
                        proposed = false,
                    ),
                    Transition(
                        index = 5,
                        from = setOf(OrderState.PENDING_VERIFICATION),
                        on = OrderCommand.Verify,
                        guard =
                            listOf(
                                OrderPredicate.NOT_RETURNED,
                                OrderPredicate.VERIFIER_IS_PHARMACIST,
                                OrderPredicate.CONTROL_SET_A_MISMATCH,
                            ),
                        to = OrderState.PENDING_VERIFICATION,
                        effects = listOf(OrderEffect.RETURN_TO_PRESCRIBER, OrderEffect.FLAG_IF_IDENTITY_NOT_REVERIFIED),
                        proposed = true,
                    ),
                    Transition(
                        index = 6,
                        from = setOf(OrderState.PENDING_VERIFICATION),
                        on = OrderCommand.ReturnToPrescriber,
                        guard =
                            listOf(
                                OrderPredicate.NOT_RETURNED,
                                OrderPredicate.VERIFIER_IS_PHARMACIST,
                                OrderPredicate.RETURN_REASON_ENTERED,
                            ),
                        to = OrderState.PENDING_VERIFICATION,
                        effects = listOf(OrderEffect.RETURN_TO_PRESCRIBER, OrderEffect.FLAG_IF_IDENTITY_NOT_REVERIFIED),
                        proposed = true,
                    ),
                    Transition(
                        index = 7,
                        from = setOf(OrderState.PENDING_VERIFICATION),
                        on = OrderCommand.Resubmit,
                        guard =
                            listOf(
                                OrderPredicate.VERIFICATION_RETURNED,
                                OrderPredicate.ACTOR_PRIVILEGED,
                                OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED,
                                OrderPredicate.PRESCRIBER_RESPONSE_RECORDED,
                            ),
                        to = OrderState.PENDING_VERIFICATION,
                        effects = listOf(OrderEffect.RESUBMIT_FOR_VERIFICATION),
                        proposed = true,
                    ),
                    Transition(
                        index = 8,
                        from = setOf(OrderState.ACTIVE),
                        on = OrderCommand.Hold,
                        guard = listOf(OrderPredicate.MAY_HOLD_ORDER, OrderPredicate.HOLD_REASON_ENTERED),
                        to = OrderState.ON_HOLD,
                        effects = listOf(OrderEffect.SUSPEND_FULFILMENT, OrderEffect.FLAG_IF_IDENTITY_NOT_REVERIFIED),
                        proposed = false,
                    ),
                    Transition(
                        index = 9,
                        from = setOf(OrderState.PENDING_VERIFICATION),
                        on = OrderCommand.Hold,
                        guard = listOf(OrderPredicate.MAY_HOLD_ORDER, OrderPredicate.HOLD_REASON_ENTERED),
                        to = OrderState.ON_HOLD,
                        effects = listOf(OrderEffect.SUSPEND_FULFILMENT, OrderEffect.FLAG_IF_IDENTITY_NOT_REVERIFIED),
                        proposed = true,
                    ),
                    Transition(
                        index = 10,
                        from = setOf(OrderState.ON_HOLD),
                        on = OrderCommand.HoldReviewDue,
                        guard = listOf(OrderPredicate.HOLD_REVIEW_DUE),
                        to = OrderState.ON_HOLD,
                        effects = listOf(OrderEffect.CREATE_HOLD_REVIEW_TASK),
                        proposed = true,
                    ),
                    Transition(
                        index = 11,
                        from = setOf(OrderState.ON_HOLD),
                        on = OrderCommand.Resume,
                        guard =
                            listOf(
                                OrderPredicate.ACTOR_PRIVILEGED,
                                OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED,
                                OrderPredicate.VERIFIED_OR_NOT_MEDICATION,
                            ),
                        to = OrderState.ACTIVE,
                        effects = listOf(OrderEffect.RESUME_FULFILMENT),
                        proposed = false,
                    ),
                    Transition(
                        index = 12,
                        from = setOf(OrderState.ON_HOLD),
                        on = OrderCommand.Resume,
                        guard =
                            listOf(
                                OrderPredicate.ACTOR_PRIVILEGED,
                                OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED,
                                OrderPredicate.MEDICATION_AWAITING_VERIFICATION,
                            ),
                        to = OrderState.PENDING_VERIFICATION,
                        effects = listOf(OrderEffect.RESUME_FULFILMENT),
                        proposed = true,
                    ),
                    Transition(
                        index = 13,
                        from = setOf(OrderState.ACTIVE),
                        on = OrderCommand.Complete,
                        guard = listOf(OrderPredicate.FULFILMENT_COMPLETE),
                        to = OrderState.COMPLETED,
                        effects = listOf(OrderEffect.CLOSE_OPEN_FULFILMENT, OrderEffect.CLOSE_ORDER_TRACKING),
                        proposed = false,
                    ),
                    Transition(
                        index = 14,
                        from = setOf(OrderState.ACTIVE),
                        on = OrderCommand.Discontinue,
                        guard =
                            listOf(
                                OrderPredicate.MAY_DISCONTINUE_ORDER,
                                OrderPredicate.REASON_IS_NOT_REPLACEMENT,
                                OrderPredicate.DISCONTINUE_REASON_ENTERED,
                            ),
                        to = OrderState.REVOKED,
                        effects =
                            listOf(
                                OrderEffect.CLOSE_OPEN_FULFILMENT,
                                OrderEffect.CLOSE_ORDER_TRACKING,
                                OrderEffect.PUBLISH_ORDER_DISCONTINUED,
                                OrderEffect.FLAG_IF_IDENTITY_NOT_REVERIFIED,
                            ),
                        proposed = false,
                    ),
                    Transition(
                        index = 15,
                        from = setOf(OrderState.PENDING_VERIFICATION, OrderState.ON_HOLD),
                        on = OrderCommand.Discontinue,
                        guard =
                            listOf(
                                OrderPredicate.MAY_DISCONTINUE_ORDER,
                                OrderPredicate.REASON_IS_NOT_REPLACEMENT,
                                OrderPredicate.DISCONTINUE_REASON_ENTERED,
                            ),
                        to = OrderState.REVOKED,
                        effects =
                            listOf(
                                OrderEffect.CLOSE_OPEN_FULFILMENT,
                                OrderEffect.CLOSE_ORDER_TRACKING,
                                OrderEffect.PUBLISH_ORDER_DISCONTINUED,
                                OrderEffect.FLAG_IF_IDENTITY_NOT_REVERIFIED,
                            ),
                        proposed = true,
                    ),
                    Transition(
                        index = 16,
                        from = setOf(OrderState.PENDING_VERIFICATION, OrderState.ACTIVE, OrderState.ON_HOLD),
                        on = OrderCommand.Discontinue,
                        guard =
                            listOf(
                                OrderPredicate.MAY_DISCONTINUE_ORDER,
                                OrderPredicate.REASON_IS_REPLACEMENT,
                                OrderPredicate.REPLACING_ORDER_SIGNED_TOGETHER,
                            ),
                        to = OrderState.REVOKED,
                        effects =
                            listOf(
                                OrderEffect.LINK_REPLACING_ORDER,
                                OrderEffect.CLOSE_OPEN_FULFILMENT,
                                OrderEffect.CLOSE_ORDER_TRACKING,
                            ),
                        proposed = true,
                    ),
                    Transition(
                        index = 17,
                        from = setOf(OrderState.ACTIVE),
                        on = OrderCommand.MarkEnteredInError,
                        guard =
                            listOf(
                                OrderPredicate.PRIVILEGED_AND_AUDITED,
                                OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED,
                                OrderPredicate.ERROR_REASON_ENTERED,
                            ),
                        to = OrderState.ENTERED_IN_ERROR,
                        effects =
                            listOf(
                                OrderEffect.FLAG_ENTERED_IN_ERROR,
                                OrderEffect.CLOSE_OPEN_FULFILMENT,
                                OrderEffect.CLOSE_ORDER_TRACKING,
                            ),
                        proposed = false,
                    ),
                    Transition(
                        index = 18,
                        from = setOf(OrderState.PENDING_VERIFICATION, OrderState.ON_HOLD),
                        on = OrderCommand.MarkEnteredInError,
                        guard =
                            listOf(
                                OrderPredicate.PRIVILEGED_AND_AUDITED,
                                OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED,
                                OrderPredicate.ERROR_REASON_ENTERED,
                            ),
                        to = OrderState.ENTERED_IN_ERROR,
                        effects =
                            listOf(
                                OrderEffect.FLAG_ENTERED_IN_ERROR,
                                OrderEffect.CLOSE_OPEN_FULFILMENT,
                                OrderEffect.CLOSE_ORDER_TRACKING,
                            ),
                        proposed = true,
                    ),
                    Transition(
                        index = 19,
                        from = setOf(OrderState.COMPLETED, OrderState.REVOKED),
                        on = OrderCommand.MarkEnteredInError,
                        guard =
                            listOf(
                                OrderPredicate.PRIVILEGED_AND_AUDITED,
                                OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED,
                                OrderPredicate.ERROR_REASON_ENTERED,
                            ),
                        to = OrderState.ENTERED_IN_ERROR,
                        effects = listOf(OrderEffect.FLAG_ENTERED_IN_ERROR),
                        proposed = true,
                    ),
                ),
        )

    /** Evaluates [predicate] with the domain's single implementation [predicates]. */
    @Suppress("CyclomaticComplexMethod")
    fun holds(
        predicate: OrderPredicate,
        predicates: OrderPredicates,
        facts: OrderFacts,
    ): Boolean =
        when (predicate) {
            OrderPredicate.MEDICATION_ORDER -> predicates.medicationOrder(facts)
            OrderPredicate.NOT_MEDICATION_ORDER -> predicates.notMedicationOrder(facts)
            OrderPredicate.SIGNER_AUTHENTICATED_HUMAN -> predicates.signerAuthenticatedHuman(facts)
            OrderPredicate.ORDERER_PRIVILEGED -> predicates.ordererPrivileged(facts)
            OrderPredicate.ACTOR_PRIVILEGED -> predicates.actorPrivileged(facts)
            OrderPredicate.MAY_HOLD_ORDER -> predicates.mayHoldOrder(facts)
            OrderPredicate.MAY_DISCONTINUE_ORDER -> predicates.mayDiscontinueOrder(facts)
            OrderPredicate.VERIFIER_IS_PHARMACIST -> predicates.verifierIsPharmacist(facts)
            OrderPredicate.VERIFIER_INDEPENDENT_OF_ORDERER -> predicates.verifierIndependentOfOrderer(facts)
            OrderPredicate.IDENTITY_REVERIFICATION_SATISFIED -> predicates.identityReverificationSatisfied(facts)
            OrderPredicate.NOT_OFFLINE_WITHOUT_FULL_CDS -> predicates.notOfflineWithoutFullCds(facts)
            OrderPredicate.LOCAL_HARD_STOPS_SATISFIED -> predicates.localHardStopsSatisfied(facts)
            OrderPredicate.KB_HARD_STOP_NOT_FIRED -> predicates.kbHardStopNotFired(facts)
            OrderPredicate.INTERRUPTIVE_ALERTS_ANSWERED -> predicates.interruptiveAlertsAnswered(facts)
            OrderPredicate.CDS_GAPS_REVIEWED -> predicates.cdsGapsReviewed(facts)
            OrderPredicate.CO_SIGN_RULE_SATISFIED -> predicates.coSignRuleSatisfied(facts)
            OrderPredicate.VERBAL_ORDER_PERMITTED -> predicates.verbalOrderPermitted(facts)
            OrderPredicate.VERBAL_ORDER_DOCUMENTED -> predicates.verbalOrderDocumented(facts)
            OrderPredicate.NOT_VERBAL_ANTINEOPLASTIC -> predicates.notVerbalAntineoplastic(facts)
            OrderPredicate.RESTRICTED_ANTIMICROBIAL_APPROVED -> predicates.restrictedAntimicrobialApproved(facts)
            OrderPredicate.ANTIMICROBIAL_STOP_OR_REVIEW_DATE_SET -> predicates.antimicrobialStopOrReviewDateSet(facts)
            OrderPredicate.INDICATION_RECORDED_WHERE_REQUIRED -> predicates.indicationRecordedWhereRequired(facts)
            OrderPredicate.DATED_WEIGHT_RECORDED_IF_WEIGHT_BASED -> predicates.datedWeightRecordedIfWeightBased(facts)
            OrderPredicate.REPLACED_ORDER_DISCONTINUABLE -> predicates.replacedOrderDiscontinuable(facts)
            OrderPredicate.NOT_RETURNED -> predicates.notReturned(facts)
            OrderPredicate.VERIFICATION_RETURNED -> predicates.verificationReturned(facts)
            OrderPredicate.CONTROL_SET_A_SATISFIED -> predicates.controlSetASatisfied(facts)
            OrderPredicate.CONTROL_SET_A_MISMATCH -> predicates.controlSetAMismatch(facts)
            OrderPredicate.RETURN_REASON_ENTERED -> predicates.returnReasonEntered(facts)
            OrderPredicate.PRESCRIBER_RESPONSE_RECORDED -> predicates.prescriberResponseRecorded(facts)
            OrderPredicate.HOLD_REASON_ENTERED -> predicates.holdReasonEntered(facts)
            OrderPredicate.VERIFIED_OR_NOT_MEDICATION -> predicates.verifiedOrNotMedication(facts)
            OrderPredicate.MEDICATION_AWAITING_VERIFICATION -> predicates.medicationAwaitingVerification(facts)
            OrderPredicate.DRAFT_REVIEW_DUE -> predicates.draftReviewDue(facts)
            OrderPredicate.HOLD_REVIEW_DUE -> predicates.holdReviewDue(facts)
            OrderPredicate.FULFILMENT_COMPLETE -> predicates.fulfilmentComplete(facts)
            OrderPredicate.REASON_IS_REPLACEMENT -> predicates.reasonIsReplacement(facts)
            OrderPredicate.REASON_IS_NOT_REPLACEMENT -> predicates.reasonIsNotReplacement(facts)
            OrderPredicate.DISCONTINUE_REASON_ENTERED -> predicates.discontinueReasonEntered(facts)
            OrderPredicate.REPLACING_ORDER_SIGNED_TOGETHER -> predicates.replacingOrderSignedTogether(facts)
            OrderPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
            OrderPredicate.ERROR_REASON_ENTERED -> predicates.errorReasonEntered(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: OrderState,
        command: OrderCommand,
        predicates: OrderPredicates,
        facts: OrderFacts,
    ): Outcome<OrderState, OrderCommand, OrderPredicate, OrderEffect> = spec.fire(state, command) { holds(it, predicates, facts) }
}
